import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"UI refresh — implementation plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/ui-refresh/plan.md","filePath":"feature/media-package-campaign/ui-refresh/plan.md"}'),r={name:"feature/media-package-campaign/ui-refresh/plan.md"};function o(l,e,s,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ui-refresh-—-implementation-plan" tabindex="-1">UI refresh — implementation plan <a class="header-anchor" href="#ui-refresh-—-implementation-plan" aria-label="Permalink to &quot;UI refresh — implementation plan&quot;">​</a></h1><h2 id="implementation-amendment-—-2026-10-19" tabindex="-1">Implementation amendment — 2026-10-19 <a class="header-anchor" href="#implementation-amendment-—-2026-10-19" aria-label="Permalink to &quot;Implementation amendment — 2026-10-19&quot;">​</a></h2><ol><li><p>Reuse compact PageWrapper per-page only; small accessible HelpHint disclosure replaces secondary copy. Group OfferingSummary per deliverable with labelled description/acceptance and quantity; show budget/duration separately, not huge fallback text.</p></li><li><p>Workspace Package: selected summary visible by default; top Change package switches to catalogue in-page with Back action, preserved existing select handlers/error/approval guards; no duplicate always-visible catalogue below detail.</p></li><li><p>Campaign: compact wrapper/stage row, remove duplicate partner navigation/heading; contextual help for milestones/work items and policy hints. Date utility uses date-fns calendar-day arithmetic, date-only strings and approved duration; manual dates remain editable/preserved.</p></li><li><p>Remove Task Detail approval shortcut. Scope PageWrapper child-height override to task-approvals so its body flexes and long preview scrolls independently; no global CSS/primitive change.</p></li><li><p>Parallel vi/en Package/Campaign labels, lint/typecheck/Vite and browser fixtures with very long terms/media, 375/768/1440 light/dark. No src tests or shared DB mutations, commit/push only if requested.</p></li><li><p>Use existing Inter/type scale, semantic background/card/foreground/border and brand-orange tokens. Quiet panels, left-aligned content, one primary action per section; no new font, global style or library. Desktop negotiation uses a wide terms panel plus approval sidebar; mobile stacks the same sections.</p></li><li><p>Change only pages/media-package, pages/campaign and pages/chat. Add local presentation helpers as needed. Preserve existing service requests and hooks. Keep partner links; do not edit partner pages or shared navigation.</p></li><li><p>Catalogue: local search and availability filter; detail dialog; grouped form, pending/dirty-dismiss protection. Negotiation: reusable labelled term comparison, responsive old/new columns, approval summary and Campaign link.</p></li><li><p>Campaign: plan/read/review/delivery panels, snapshot context, structured version comparison, readable state/Task labels and existing deployment/completion actions.</p></li><li><p>Chat: header, connection notice, scroll area/day groups, message roles/timestamps, sending/error feedback and composer hint; keep realtime transport untouched.</p></li><li><p>Locale files: src/i18n/locales/{vi,en}/{mediaPackage,campaign,chat}.json. Preserve current partner keys and unrelated translations.</p></li><li><p>Run existing media-package and partner regression tests (no generated test-spec rewrite), type-check, lint and build. Use Playwright CLI for screenshots/flows against a local or isolated mock session, never seed or mutate shared data.</p></li><li><p>Verify git diff excludes shared UI/routes/services/hooks and existing unrelated edits. Document evidence and limitations in test.md/task.md.</p></li></ol><p>Main risks: snapshot terms versus mutable catalogue, accidental loss of approvals, dirty forms, long content/mobile overflow and accidentally widening role permissions. UI work must not change any of those business rules.</p><h2 id="correction-plan-—-2026-10-11" tabindex="-1">Correction plan — 2026-10-11 <a class="header-anchor" href="#correction-plan-—-2026-10-11" aria-label="Permalink to &quot;Correction plan — 2026-10-11&quot;">​</a></h2><p>Milestone/work-item clarification: group all milestone controls in their own section in CampaignForm, name the separate WorkItemsEditor section, and replace the shared itemName key with milestoneName/workItemName in vi/en campaign.json. Preserve independent add/remove handlers, timeline serialization and workItems.</p><ol><li>Catalogue: use Input.iconPrefix rather than an external overlay; size the Select wrapper via wrapperClassName and allow toolbar wrapping. Keep result count nowrap.</li><li>Update Vietnamese approval copy in mediaPackage/campaign; keep English keys and add campaign.ui.editLocked to both vi/en.</li><li>Campaign page: prefer URL Workspace role from workspaceList; only fall back to currentWorkspace/currentMemberRole when its ID matches. Expose a disabled edit action and lock explanation for Manager non-draft plans; preserve existing APIs.</li><li>CLI fixture audit: Owner search/filter bounding boxes, responsive themes, Vietnamese approval labels, Manager draft edit/save and immutable-state lock; Client must still have no edit control. Run type-check/scoped lint/build.</li><li>With explicit user approval, transactionally restore the single identified draft&#39;s empty deliverable_plan from its own frozen snapshot. Require matching Workspace, DRAFT, no allocation period, matching approved v3 snapshot, 2 source deliverables and DELIVERABLE_BUNDLE model. Abort if target predicates no longer match. Advance only the internal row_version lock token to invalidate stale in-flight JPA writes; content_version remains 1. Normal updated_at trigger may run.</li></ol>',7)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
